import * as fs from "fs";
import * as path from "path";
import { checkpoint } from "@tigrisdata/agent-kit";

async function main() {
  try {
    const projectDir = "/home/user/ckpt-tag";
    const buildIdPath = path.join(projectDir, "build_id.txt");
    const buildId = fs.readFileSync(buildIdPath, "utf-8").trim();

    const unixTimestamp = Math.floor(Date.now() / 1000);
    const name = `release-${buildId}-${unixTimestamp}`;

    console.log(`Taking checkpoint: ${name}`);

    const { data: ckpt, error } = await checkpoint("agent-pipeline-data", { name });

    if (error) {
      console.error("Checkpoint error:", error);
      process.exit(1);
    }

    if (!ckpt || !ckpt.snapshotId) {
        console.error("Checkpoint succeeded but snapshotId is missing");
        process.exit(1);
    }

    const result = {
      snapshotId: ckpt.snapshotId,
      name: name
    };

    const outputPath = path.join(projectDir, "snapshot.json");
    fs.writeFileSync(outputPath, JSON.stringify(result, null, 2));
    console.log(`Snapshot info saved to ${outputPath}`);
    process.exit(0);
  } catch (err) {
    console.error("Unexpected error:", err);
    process.exit(1);
  }
}

main();

